class Solution {
 int count(vector<vector<int>>& g){
  int m=g.size(),n=g[0].size(),ans=0;
  vector<vector<int>> dp(m,vector<int>(n));
  for(int i=m-1;i>=0;--i) for(int j=0;j<n;++j) if(g[i][j]){
   dp[i][j]=1;
   if(i+1<m && j>0 && j+1<n)
    dp[i][j]+=min(dp[i+1][j],min(dp[i+1][j-1],dp[i+1][j+1]));
   ans+=dp[i][j]-1;
  }
  return ans;
 }
public:
 int countPyramids(vector<vector<int>>& grid){
  int ans=count(grid);reverse(grid.begin(),grid.end());return ans+count(grid);
 }
};
